/** Google Calendar event bodies for tentative holds on the slots the reply offered. */
function holdEvents(slots, row, timezone = "Europe/London", nowMs = Date.now()) {
  const expires = new Date(nowMs + HOLD_DAYS * 24 * 3600 * 1000);
