  }
  const icon = { sent: "✅", simulated: "✅", rejected: "🚫", failed: "⚠️" }[outcome.status] ?? "ℹ️";
  const text = outcome.status === "rejected"
    ? `${icon} *Rejected* by ${slackEscape(outcome.by, 80)}${outcome.reason ? `: ${slackEscape(outcome.reason, 300)}` : ""}`
